const asExample = ([en, th, note]: ExampleRow) => ({ en, th, note })

export const foundationPatterns: Pattern[] = patternRows.map((
  [id, lesson, template, meaning, intent, name, rule, example, why, placement, first, second, alternative],
) => ({
  id, template, meaning, intent, register: 'neutral',
  slots: [{ name, rule, example }], examples: [asExample(first), asExample(second)],
  why, placement, alternatives: [alternative], mistakes: [], lessons: [lesson], tags: [intent],
}))

export const foundationLessons: Lesson[] = lessonRows.map((row) => ({
  id: row.id, module: Number(row.id[1]), titleEn: row.title[0], titleTh: row.title[1],
  hook: row.hook, objective: row.purpose, concept: row.concept, formula: row.formula,
  minutes: 8, prerequisites: row.prerequisites ?? [], tags: row.tags,
  examples: row.examples.map(asExample),
  contrasts: row.contrasts.map(([a, b, note]) => ({ a, b, note })),
  dialogue: row.dialogue.map(([en, th]) => ({ en, th })),
  mistakes: row.mistakes.map(([wrong, right, note]) => ({ wrong, right, note })),
  exercises: row.tasks.map(([kind, prompt, answers, explanation, options], index) => ({
    id: `${row.id}-e${index + 1}`,
    kind, prompt, answers: Array.isArray(answers) ? answers : [answers], hint: row.formula, explanation,
    ...(options ? { options } : {}),
    difficulty: kind === 'translate' ? 'production' : kind === 'repair' || kind === 'transform' ? 'guided' : 'recognition',
  })),
  speaking: row.speaking,
  review: foundationPatterns.filter((pattern) => pattern.lessons.includes(row.id)).map((pattern) => pattern.id),
}))
